window.AmiriBase64 = '';
/* ============================================================
   orders.js  –  Order Management Logic
   ============================================================ */

let clients = [];
let products = [];
let cart = [];

let clientChoices;
let productChoices;

// Stores the supplier cost price fetched from DB when a product is selected.
// Each cart item SNAPSHOTS this at add-time — frozen and immutable per row.
let currentCostPrice = 0;

document.addEventListener('DOMContentLoaded', () => {
    loadClients();
    loadWarehouses();
    // Products will now load dynamically AFTER a warehouse is selected
    loadOrders();

    // Setup today's date for expected delivery
    const today = new Date().toISOString().split('T')[0];
    document.getElementById('expected-delivery').value = today;

    // NOTE: changing the margin input does NOT reprice existing rows.
    // It only affects the NEXT item added to the cart.
});

/* ── Load Data ──────────────────────────────── */
async function loadClients() {
    try {
        const [docsRes, pharmRes] = await Promise.all([
            fetch('/api/doctors'),
            fetch('/api/pharmacies')
        ]);

        let doctors = [], pharmacies = [];
        if (docsRes.ok) doctors = await docsRes.json();
        if (pharmRes.ok) pharmacies = await pharmRes.json();

        console.log('loadClients: doctors=', doctors.length, 'pharmacies=', pharmacies.length);

        const select = document.getElementById('client-select');

        // Clear existing items to prevent duplicates on re-invoke
        // Keep only the first blank option if it exists
        while (select.options.length > 0 && select.options[0].value !== '') {
            select.remove(0);
        }
        // Remove all optgroups
        Array.from(select.querySelectorAll('optgroup')).forEach(g => g.remove());

        const optgroupDocs = document.createElement('optgroup');
        optgroupDocs.label = 'Doctors & Hospitals';
        doctors.forEach(d => {
            optgroupDocs.appendChild(new Option(`⚕️ Dr: ${d.name.replace('د. ', '')}`, `doc-${d.id}`));
        });
        select.appendChild(optgroupDocs);

        const optgroupPharms = document.createElement('optgroup');
        optgroupPharms.label = 'Pharmacies';
        pharmacies.forEach(p => {
            optgroupPharms.appendChild(new Option(`🏪 Pharm: ${p.name}`, `pharm-${p.id}`));
        });
        select.appendChild(optgroupPharms);

        // Initialization of choices
        if (clientChoices) {
            clientChoices.destroy();
        }

        clientChoices = new Choices(select, {
            searchEnabled: true,
            itemSelectText: '',
            shouldSort: false,
            searchPlaceholderValue: 'بحث عن مستشفى أو صيدلية...',
            noResultsText: 'لا توجد نتائج',
            noChoicesText: 'لا يوجد عملاء للاختيار'
        });

        // Auto-select from URL if present
        const urlParams = new URLSearchParams(window.location.search);
        const presetClient = urlParams.get('client');
        if (presetClient) {
            const exists = Array.from(select.options).some(o => o.value === presetClient);
            if (exists) {
                clientChoices.setChoiceByValue(presetClient);
                setTimeout(() => handleClientSelect(presetClient), 100);
            }
        }

    } catch (err) { console.error('Error loading clients:', err); }
}

async function loadWarehouses() {
    try {
        const res = await fetch('/api/warehouse/list');
        const warehouses = await res.json();
        const select = document.getElementById('warehouse-select');
        warehouses.forEach(w => {
            select.add(new Option(w.name, w.id));
        });
    } catch (err) { console.error('Error loading warehouses:', err); }
}

async function handleWarehouseSelect(warehouseId) {
    // DO NOT Clear product cart since we now allow cross-warehouse checkout

    const productSelect = document.getElementById('product-select');

    if (productChoices) {
        productChoices.destroy();
    }

    productSelect.innerHTML = '<option value="" disabled selected>جاري تحميل المخزون...</option>';
    productSelect.disabled = true;

    try {
        const res = await fetch(`/api/warehouse/${warehouseId}/inventory`);
        products = await res.json();

        productSelect.innerHTML = '<option value="" selected>اختر صنف...</option>';
        if (products.length > 0) {
            const grouped = {};
            products.forEach(p => {
                if (!grouped[p.id]) {
                    grouped[p.id] = { ...p, quantity: 0 };
                }
                grouped[p.id].quantity += parseInt(p.quantity || 0);
            });

            // Reassign products to the grouped version so cart logic works with correct total stock
            products = Object.values(grouped);

            products.forEach(p => {
                const stockStr = typeof formatUoM === 'function' ? formatUoM(p.quantity, p.base_uom_name, p.bulk_uom_name, p.conversion_factor) : p.quantity;
                productSelect.add(new Option(`${p.name} - (Total Stock: ${stockStr})`, p.id));
            });
            productSelect.disabled = false;
            productChoices = new Choices(productSelect, {
                searchEnabled: true,
                itemSelectText: '',
                shouldSort: false,
                searchPlaceholderValue: 'بحث عن صنف...',
                noResultsText: 'لا توجد نتائج',
                noChoicesText: 'لا توجد أصناف للاختيار'
            });
            // Event listener moved to top-level handleProductSelect function
        } else {
            productSelect.innerHTML = '<option value="" disabled selected>No stock available here.</option>';
            productChoices = new Choices(productSelect, {
                searchEnabled: true,
                itemSelectText: '',
                shouldSort: false
            });
            productChoices.disable();
        }
    } catch (err) { console.error('Error loading warehouse inventory:', err); }
}

async function handleProductSelect(productId) {
    if (!productId) return;
    const product = products.find(prod => prod.id == productId);
    console.log('Selected Product Object in Orders:', product);

    // ── Fetch the supplier purchase_price from the DB ──────────────────────
    currentCostPrice = 0; // reset before fetching
    if (product) {
        try {
            const costRes = await fetch(`/api/orders/product/${product.id}/cost-price`);
            if (costRes.ok) {
                const costData = await costRes.json();
                currentCostPrice = parseFloat(costData.cost_price) || 0;
                console.log(`Cost price for "${product.name}": ${currentCostPrice}`);
            } else {
                console.warn('Could not fetch cost price, falling back to 0.');
            }
        } catch (err) {
            console.error('Cost price fetch error:', err);
        }
    }

    const unitSelect = document.getElementById('order-unit');
    if (unitSelect && product) {
        unitSelect.innerHTML = '';
        const baseName = product.base_uom_name || 'Piece';
        unitSelect.add(new Option(baseName, 'BASE'));
        if (product.bulk_uom_name && product.conversion_factor > 1) {
            unitSelect.add(new Option(product.bulk_uom_name, 'BULK'));
        }
        unitSelect.value = 'BASE';
    }

    // Fetch batches explicitly
    const warehouseId = document.getElementById('warehouse-select').value;
    const batchSelect = document.getElementById('item-batch-select');
    if (batchSelect && product && warehouseId) {
        batchSelect.innerHTML = '<option value="" disabled selected>Loading batches...</option>';
        batchSelect.disabled = true;

        try {
            const res = await fetch(`/api/inventory/batches/${warehouseId}/${product.id}`);
            if (!res.ok) throw new Error('Network error querying batches');
            const batches = await res.json();

            window.currentBatches = batches; // Track globally for add item limits
            batchSelect.innerHTML = '<option value="AUTO">AUTO (FEFO Rollover)</option>';

            if (batches && batches.length > 0) {
                batches.forEach(b => {
                    const exp = b.expiry_date ? new Date(b.expiry_date).toLocaleDateString('en-GB') : 'No Expiry';
                    batchSelect.add(new Option(`Batch: ${b.batch_number || b.id} - Expiry: ${exp} - Stock: ${b.current_stock}`, b.id));
                });
            } else {
                console.warn('No specific batch details found. Product might be tracking total bulk.');
            }
            batchSelect.disabled = false;
            batchSelect.selectedIndex = 0; // Select AUTO
        } catch (err) {
            console.error('Batch fetch err:', err);
            window.currentBatches = [];
            batchSelect.innerHTML = '<option value="AUTO">AUTO (FEFO Rollover)</option>';
            batchSelect.disabled = false;
        }
    }
}

/* ── Pagination State ───────────────────────── */
const PAGE_INITIAL = 3;    // rows shown on load
const PAGE_STEP = 2;    // rows added per "View More"
let ordersOffset = 0;    // how many rows are already displayed
let ordersTotal = 0;    // total rows in DB

async function loadOrders(reset = true) {
    if (reset) {
        ordersOffset = 0;
        document.getElementById('orders-tbody').innerHTML =
            '<tr><td colspan="6" class="text-center text-muted">Loading orders...</td></tr>';
        const existingBtn = document.getElementById('view-more-btn');
        if (existingBtn) existingBtn.remove();
    }

    const limit = reset ? PAGE_INITIAL : PAGE_STEP;
    try {
        const res = await fetch(`/api/orders?limit=${limit}&offset=${ordersOffset}`);
        const data = await res.json();
        const orders = data.orders || data; // backward compat
        ordersTotal = data.total ?? orders.length;

        if (reset) {
            renderOrdersTable(orders);
        } else {
            appendOrderRows(orders);
        }
        ordersOffset += orders.length;
        updateViewMoreButton();
    } catch (err) { console.error('Error loading orders:', err); }
}

/* ── Order Form Logic ───────────────────────── */
function addOrderItem() {
    const productSelect = document.getElementById('product-select');
    const qtyInput = document.getElementById('item-qty');
    const warehouseSelect = document.getElementById('warehouse-select');

    if (!warehouseSelect.value) {
        alert('Please select a warehouse first.');
        return;
    }

    const warehouseId = warehouseSelect.value;
    const warehouseName = warehouseSelect.options[warehouseSelect.selectedIndex].text;

    const productId = productSelect.value;
    const qty = parseInt(qtyInput.value);

    const marginInput = document.getElementById('profit-margin-input');
    let marginVal = parseFloat(marginInput.value);

    // Prevent negative numbers and invalid inputs
    if (isNaN(marginVal) || marginVal < 0) {
        alert('Please enter a valid positive number for Profit Margin.');
        return;
    }
    const margin = marginVal / 100.0; // e.g. 12.5 -> 0.125

    if (!productId || isNaN(qty) || qty <= 0) {
        alert('Please select a valid product and quantity.');
        return;
    }

    const product = products.find(p => p.id == productId);
    if (!product) return;

    console.log('Adding product:', product);

    const availableStock = product.quantity || 0;
    const unitSelect = document.getElementById('order-unit');
    let factor = 1;
    let unitLabel = product.base_uom_name || 'Unit';

    if (unitSelect && unitSelect.value === 'BULK') {
        factor = parseInt(product.conversion_factor) || 1;
        unitLabel = product.bulk_uom_name || 'Bulk Unit';
    }

    const baseQty = qty * factor;

    if (baseQty > availableStock) {
        const stockStr = typeof formatUoM === 'function' ? formatUoM(availableStock, product.base_uom_name, product.bulk_uom_name, product.conversion_factor) : availableStock;
        alert(`Cannot add ${qty} ${unitLabel}. Only ${stockStr} currently available in this Warehouse.`);
        return;
    }

    const batchSelect = document.getElementById('item-batch-select');
    const selectedBatchId = batchSelect ? batchSelect.value : 'AUTO';
    const finalInventoryId = selectedBatchId === 'AUTO' ? null : parseInt(selectedBatchId);

    // Strict batch limit checking
    if (finalInventoryId) {
        const batch = window.currentBatches?.find(b => b.id === finalInventoryId);
        if (batch) {
            if (baseQty > batch.current_stock) {
                alert(`Insufficient stock in this specific batch. You requested ${qty} ${unitLabel} (${baseQty} base units), but only ${batch.current_stock} base units are available in Batch ${batch.batch_number || batch.id}. Please adjust the quantity and add the remainder from another batch as a separate line item.`);
                return;
            }
        }
    }

    // Use the supplier COST price (purchase_price) fetched from the DB.
    // currentCostPrice is populated by handleProductSelect via /api/orders/product/:id/cost-price.
    // The margin is SNAPSHOTTED here — changing the input later will NOT change this row.
    const basePrice = currentCostPrice * factor; // cost price, adjusted for bulk factor
    const unitPrice = basePrice * (1 + margin);  // selling price = cost * (1 + margin%)

    // Check if already in cart (need to match inventory_id as well now, and warehouseId)
    const existing = cart.find(i => i.product_id == productId && i.unit_value === (unitSelect ? unitSelect.value : 'BASE') && i.inventory_id === finalInventoryId && i.warehouse_id === warehouseId);
    if (existing) {
        existing.qty += qty;
        existing.base_qty += baseQty;
        // Strict limit check again before appending!
        if (finalInventoryId && window.currentBatches) {
            const batch = window.currentBatches.find(b => b.id === finalInventoryId);
            if (batch && existing.base_qty > batch.current_stock) {
                alert(`Combining this brings your total to ${existing.base_qty} base units, which exceeds the ${batch.current_stock} available in this batch.`);
                existing.qty -= qty; // rollback
                existing.base_qty -= baseQty;
                return;
            }
        }

        // Row prices are IMMUTABLE once added. Only quantity increases.
        // Do NOT update profit_margin / base_price / unit_price here.
        existing.subtotal = existing.qty * existing.unit_price;
    } else {
        const batchDisplay = batchSelect && finalInventoryId ? batchSelect.options[batchSelect.selectedIndex].text.split(' - ')[0] : 'AUTO Batch';
        cart.push({
            product_id: productId,
            warehouse_id: warehouseId,
            warehouse_name: warehouseName,
            inventory_id: finalInventoryId, // Null means Auto
            batch_display: batchDisplay,
            name: product.name,
            qty: qty,
            base_qty: baseQty,
            unit_label: unitLabel, // Use actual label (e.g. 'Carton' or 'Piece')
            unit_value: unitSelect ? unitSelect.value : 'BASE',
            base_price: basePrice,
            profit_margin: margin,
            unit_price: unitPrice,
            subtotal: qty * unitPrice
        });
    }

    // Reset batch logic to safe default
    if (batchSelect) batchSelect.selectedIndex = 0;

    renderCart();

    // Reset
    if (productChoices) {
        productChoices.setChoiceByValue("");
    } else {
        productSelect.value = '';
    }
    qtyInput.value = 1;
}

function removeCartItem(idx) {
    cart.splice(idx, 1);
    renderCart();
}

function renderCart() {
    const tbody = document.getElementById('cart-tbody');
    const totalEl = document.getElementById('cart-total');

    if (cart.length === 0) {
        tbody.innerHTML = '<tr class="cart-empty"><td colspan="5" class="text-center text-muted">No items added yet</td></tr>';
        totalEl.textContent = '$0.00';
        return;
    }

    let html = '';
    let total = 0;

    cart.forEach((item, idx) => {
        total += item.subtotal;

        let displayQty = `${item.qty} ${item.unit_label || 'Unit'}`;
        if (item.qty > 1 && item.unit_label && !item.unit_label.endsWith('s') && !item.unit_label.includes('ل') && !item.unit_label.includes('ة')) {
            displayQty = `${item.qty} ${item.unit_label}s`;
        }

        html += `
               <tr>
                   <td style="font-weight:500;">${escHtml(item.name)}</td>
                   <td><span style="font-size: 0.85rem; color: #64748b; background: #f1f5f9; padding: 2px 6px; border-radius: 4px;">${escHtml(item.warehouse_name)}</span></td>
                   <td>${displayQty}</td>
                   <td>$${item.unit_price.toFixed(2)} <span style="font-size: 0.8em; color: gray;">(${(item.profit_margin * 100).toFixed(0)}%)</span></td>
                   <td style="font-weight:600;">$${item.subtotal.toFixed(2)}</td>
                   <td>
                       <button class="icon-btn" onclick="removeCartItem(${idx})" title="Remove">
                           <i class="fa-solid fa-xmark text-danger"></i>
                       </button>
                   </td>
               </tr>
           `;
    });

    tbody.innerHTML = html;
    totalEl.textContent = '$' + total.toLocaleString(undefined, { minimumFractionDigits: 2 });
}

// recalculateCart is intentionally a no-op.
// Cart rows are IMMUTABLE after being added — their price is frozen at add-time.
// Changing the margin input only affects the NEXT product to be added.
function recalculateCart() {
    renderCart(); // re-render only, prices unchanged
}

async function submitOrder() {
    const clientId = document.getElementById('client-select').value;
    const warehouseId = document.getElementById('warehouse-select').value;
    const delivery = document.getElementById('expected-delivery').value;

    if (!clientId) return alert('Please select a client.');
    if (cart.length === 0) return alert('Cannot save an empty order.');

    // Provide a global warehouse ID for backwards compatibility on the orders table. Use the first item's warehouse or fall back.
    const primaryWarehouseId = cart.length > 0 ? cart[0].warehouse_id : null;

    const payload = {
        client_id: clientId,
        warehouse_id: primaryWarehouseId,
        expected_delivery: delivery,
        items: cart.map(item => ({
            ...item,
            qty: item.base_qty || item.qty // Override qty with base_qty for backend deduction
        }))
    };

    try {
        const btn = document.querySelector('.submit-order-btn');
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Saving...';

        const res = await fetch('/api/orders', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Server error');

        // Success UI with Modal
        document.getElementById('save-order-btn').style.display = 'none';

        // Prepare data for export before clearing cart
        const exportOrderData = {
            order_number: data.order_number || ('ORD-EXT-' + Date.now()),
            client_name: document.getElementById('client-select').options[document.getElementById('client-select').selectedIndex].text.replace(/^[⚕️🏪]\s*(Dr:\s*|Pharm:\s*)?/, ''),
            client_type: clientId.startsWith('doc') ? 'doctor' : 'pharmacy',
            date: document.getElementById('expected-delivery').value || new Date().toISOString().split('T')[0],
            total_amount: cart.reduce((sum, item) => sum + item.subtotal, 0)
        };
        const exportCartData = [...cart];

        // Create success modal inline if it doesn't exist
        let modal = document.getElementById('success-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'success-modal';
            modal.className = 'modal-overlay';
            modal.style.display = 'flex';
            modal.style.position = 'fixed';
            modal.style.top = '0'; modal.style.left = '0';
            modal.style.width = '100%'; modal.style.height = '100%';
            modal.style.backgroundColor = 'rgba(0,0,0,0.5)';
            modal.style.zIndex = '9999';
            modal.style.justifyContent = 'center';
            modal.style.alignItems = 'center';
            document.body.appendChild(modal);
        }

        modal.innerHTML = `
            <div class="modal-content" style="background:#fff; padding:30px; border-radius:12px; max-width:400px; text-align:center; box-shadow:0 10px 25px rgba(0,0,0,0.1);">
                <div style="font-size:3rem; color:#10b981; margin-bottom:15px;"><i class="fa-solid fa-circle-check"></i></div>
                <h2 style="margin-bottom:10px; color:#1e293b;">Order Saved Successfully!</h2>
                <p style="color:#64748b; margin-bottom:25px;">Order <strong>${exportOrderData.order_number}</strong> has been registered as pending.</p>
                <div style="display:flex; flex-direction:column; gap:10px;">
                    <button id="btn-export-pdf" class="btn-primary" style="padding:12px; font-size:1rem; width:100%;">
                        <i class="fa-solid fa-file-pdf"></i> Print PDF Invoice
                    </button>
                    <button id="btn-export-excel" class="btn-outline" style="padding:12px; font-size:1rem; width:100%; border:1px solid #e2e8f0; color:#334155; border-radius:8px; cursor:pointer; font-weight:600;">
                        <i class="fa-solid fa-file-excel" style="color:#16a34a;"></i> Download Excel
                    </button>
                    <button id="btn-close-modal" style="background:transparent; border:none; margin-top:10px; color:#94a3b8; cursor:pointer; font-size:0.9rem; font-weight:500;">
                        Dismiss
                    </button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';

        // Bind Export Events
        document.getElementById('btn-export-pdf').onclick = () => {
            generatePDFInvoice(exportOrderData, exportCartData);
        };
        document.getElementById('btn-export-excel').onclick = () => {
            generateExcelExport(exportOrderData, exportCartData);
        };
        document.getElementById('btn-close-modal').onclick = () => {
            modal.style.display = 'none';
            // Reset form completely here after dismissing
            cart = [];
            renderCart();
            if (clientChoices) {
                clientChoices.setChoiceByValue("");
            } else {
                document.getElementById('client-select').value = '';
            }
            document.getElementById('save-order-btn').style.display = 'inline-flex';
        };

        loadOrders();

    } catch (err) {
        alert('Failed to save order: ' + err.message);
    } finally {
        const btn = document.querySelector('.submit-order-btn');
        btn.disabled = false;
        btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Save Order';
    }
}

/* ── Process Dispatch ───────────────────────── */
async function dispatchOrder(orderId, btnElement) {
    if (!confirm('Are you sure you want to Confirm & Dispatch this order? This will deduct stock and update client debt.')) return;

    // Set loading state
    const originalContent = btnElement.innerHTML;
    btnElement.disabled = true;
    btnElement.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Dispatching...';

    try {
        const res = await fetch(`/api/orders/${orderId}/dispatch`, {
            method: 'PUT'
        });
        const data = await res.json();

        if (!res.ok) {
            alert(`DISPATCH FAILED:\n\n${data.error}`);
            return;
        }

        alert('Order dispatched successfully!');
        loadOrders();

        // If the currently viewed sidebar client is the one we dispatched for, refresh sidebar.
        const currentClientId = document.getElementById('client-select').value;
        if (currentClientId) handleClientSelect(currentClientId);

    } catch (err) {
        alert('Critical Error during dispatch: ' + err.message);
    } finally {
        // Reset button state (though table will re-render, this handles errors gracefully without infinite spinner)
        btnElement.disabled = false;
        btnElement.innerHTML = originalContent;
    }
}

/* ── Process Cancel ───────────────────────── */
async function cancelOrder(orderId, btnElement) {
    if (!confirm('Are you sure you want to cancel this order? This will void the order without deducting stock.')) return;

    // Set loading state
    const originalContent = btnElement.innerHTML;
    btnElement.disabled = true;
    btnElement.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';

    try {
        const res = await fetch(`/api/orders/${orderId}/cancel`, {
            method: 'PUT'
        });

        // Check if response is JSON
        const contentType = res.headers.get("content-type");
        if (!contentType || !contentType.includes("application/json")) {
            const textHTML = await res.text();
            throw new Error(`Server returned non-JSON response (Status: ${res.status}). Ensure the server has been restarted to register the new /cancel route.`);
        }

        const data = await res.json();

        if (!res.ok) {
            alert(`CANCEL FAILED:\n\n${data.error}`);
            return;
        }

        loadOrders();
    } catch (err) {
        alert('Critical Error during cancel: ' + err.message);
    } finally {
        if (btnElement) {
            btnElement.disabled = false;
            btnElement.innerHTML = originalContent;
        }
    }
}

/* ── Sidebar & UI ───────────────────────────── */
function renderOrdersTable(orders) {
    const tbody = document.getElementById('orders-tbody');
    if (orders.length === 0 && ordersOffset === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="text-center text-muted">No orders found.</td></tr>';
        return;
    }
    tbody.innerHTML = '';
    tbody.insertAdjacentHTML('beforeend', buildOrderRows(orders));
}

function appendOrderRows(orders) {
    if (!orders.length) return;
    const tbody = document.getElementById('orders-tbody');
    const tmp = document.createElement('tbody');
    tmp.innerHTML = buildOrderRows(orders);
    Array.from(tmp.children).forEach(row => {
        row.style.opacity = '0';
        row.style.transition = 'opacity 0.35s ease';
        tbody.appendChild(row);
        requestAnimationFrame(() => requestAnimationFrame(() => { row.style.opacity = '1'; }));
    });
}

function buildOrderRows(orders) {
    return orders.map(o => {
        let badgeClass, badgeText;
        if (o.status === 'Pending') { badgeClass = 'badge-pending'; badgeText = 'Pending'; }
        else if (o.status === 'Dispatched') { badgeClass = 'badge-dispatched'; badgeText = 'Dispatched'; }
        else { badgeClass = 'badge-cancelled'; badgeText = 'Cancelled'; }

        const dateStr = new Date(o.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

        let actionBtn = '';
        if (o.status === 'Pending') {
            actionBtn = `
                <div style="display: flex; gap: 4px; align-items: center; justify-content: center;">
                    <button class="btn-action" onclick="dispatchOrder(${o.id}, this)">
                        <i class="fa-solid fa-truck-fast"></i> Confirm &amp; Dispatch
                    </button>
                    <button class="icon-btn" onclick="cancelOrder(${o.id}, this)" title="Cancel Order" style="color: #ef4444; background: #fee2e2; border-radius: 4px; padding: 4px 8px; border: 1px solid #fca5a5;">
                        <i class="fa-solid fa-xmark"></i>
                    </button>
                </div>
            `;
        } else {
            actionBtn = `<span class="text-muted" style="font-size:0.8rem;">No Actions</span>`;
        }

        actionBtn += `
            <button class="icon-btn" title="Export PDF" onclick="exportOrderPDF(${o.id})" style="margin-left: 8px; color: #dc2626;">
                <i class="fa-solid fa-file-pdf"></i>
            </button>
            <button class="icon-btn" title="Export Excel" onclick="exportOrderExcel(${o.id})" style="margin-left: 4px; color: #16a34a;">
                <i class="fa-solid fa-file-excel"></i>
            </button>
        `;

        if (o.status === 'Dispatched' || o.status === 'Returned') {
            actionBtn += `
                <button class="icon-btn" title="Return Items" onclick="openReturnModal(${o.id}, '${o.order_number}')" style="margin-left: 4px; color: #eab308;">
                    <i class="fa-solid fa-rotate-left"></i>
                </button>
            `;
        }

        return `
           <tr>
               <td style="font-weight:600; color:#475569;">${o.order_number}</td>
               <td>
                   <span class="client-initial-badge">${initials(o.client_name)}</span>
                   ${escHtml(o.client_name)}
               </td>
               <td>${dateStr}</td>
               <td style="font-weight:600;">$${Number(o.total_amount).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
               <td><span class="status-badge ${badgeClass}">${badgeText}</span></td>
               <td>${actionBtn}</td>
           </tr>
           `;
    }).join('');
}

function updateViewMoreButton() {
    const existing = document.getElementById('view-more-btn');
    const hasMore = ordersOffset < ordersTotal;

    if (!hasMore) {
        if (existing) existing.remove();
        return;
    }
    if (existing) return;

    const btn = document.createElement('div');
    btn.id = 'view-more-btn';
    btn.style.cssText = 'text-align:center; padding: 1rem 0 0.5rem;';
    btn.innerHTML = `<button onclick="loadOrders(false)" style="
        background: white; border: 1px solid #e2e8f0; color: #64748b;
        padding: 0.55rem 1.5rem; border-radius: 8px; font-size: 0.85rem;
        font-weight: 600; cursor: pointer; display: inline-flex; align-items: center;
        gap: 0.5rem; transition: all 0.2s; font-family: inherit;"
        onmouseover="this.style.borderColor='#3b82f6'; this.style.color='#3b82f6';"
        onmouseout="this.style.borderColor='#e2e8f0'; this.style.color='#64748b';">
        <i class="fa-solid fa-chevron-down" style="font-size:0.75rem;"></i> View More
    </button>`;

    const card = document.getElementById('orders-tbody')?.closest('.card');
    if (card) card.insertAdjacentElement('afterend', btn);
}




async function handleClientSelect(clientId) {
    if (!clientId) return;
    try {
        const res = await fetch(`/api/clients/${clientId}/summary`);
        if (!res.ok) throw new Error('Failed to fetch client details');
        const data = await res.json();

        // Hide empty, show sidebar
        document.getElementById('empty-sidebar-msg').style.display = 'none';
        document.getElementById('sidebar-inner').style.display = 'flex';
        document.getElementById('side-client-name').textContent = data.client.name;
        document.getElementById('side-client-address').textContent = data.client.address || 'Address not listed';
        document.getElementById('side-debt').textContent = '$' + Number(data.client.total_debt || 0).toFixed(2);

        let limit = Number(data.client.credit_limit) || 60000;
        document.getElementById('side-limit').textContent = 'Credit Limit: $' + limit.toLocaleString();

        let progress = (Number(data.client.total_debt || 0) / limit) * 100;
        if (progress > 100) progress = 100;
        document.getElementById('side-debt-progress').style.width = progress + '%';

        document.getElementById('side-avatar').textContent = initials(data.client.name);

        // Render Transaction History
        const txList = document.getElementById('side-tx-list');
        if (data.transactions && data.transactions.length > 0) {
            txList.innerHTML = data.transactions.map(tx => {
                const dateStr = new Date(tx.date).toLocaleDateString();
                const isReturn = tx.type.startsWith('RETURN');
                const typeIcon = isReturn ? 'fa-rotate-left' : (tx.type === 'ORDER' ? 'fa-cart-shopping' : 'fa-money-bill-wave');
                const bgColor = isReturn ? '#fee2e2' : '#e2e8f0';
                const iconColor = isReturn ? 'text-danger' : 'text-muted';

                return `
                    <div class="history-item" style="display:flex; justify-content:space-between; align-items:center;">
                        <div style="display:flex; align-items:center;">
                            <div class="history-dot" style="background:${bgColor}; width:32px; height:32px; display:flex; align-items:center; justify-content:center; border-radius:8px; border:none;">
                                <i class="fa-solid ${typeIcon} ${iconColor}"></i>
                            </div>
                            <div class="history-content" style="margin-left:10px;">
                                <h4 style="margin:0; font-size:14px; font-weight:600;">${tx.type}</h4>
                                <span style="font-size:13px; color:#64748b;">$${Number(Math.abs(tx.amount)).toFixed(2)}</span>
                                <div class="history-date" style="font-size:12px; color:#94a3b8;">${dateStr}</div>
                            </div>
                        </div>
                        <div style="display:flex; gap:8px;">
                            ${tx.type === 'ORDER' ? `
                            <button onclick="exportOrderPDF('${tx.reference_id}')" style="background:none; border:none; cursor:pointer; color:#ef4444;" title="Export PDF">
                                <i class="fa-solid fa-file-pdf"></i>
                            </button>
                            <button onclick="exportOrderExcel('${tx.reference_id}')" style="background:none; border:none; cursor:pointer; color:#10b981;" title="Export Excel">
                                <i class="fa-solid fa-file-excel"></i>
                            </button>
                            <button onclick="openReturnModal('${tx.reference_id}', 'ORD-${tx.reference_id}')" style="background:none; border:none; cursor:pointer; color:#eab308;" title="Return Order">
                                <i class="fa-solid fa-rotate-left"></i>
                            </button>
                            ` : ''}
                            ${isReturn ? `
                            <button onclick="generateReturnPDFFromTx('${tx.reference_id}')" style="background:none; border:none; cursor:pointer; color:#ef4444;" title="Export Return PDF">
                                <i class="fa-solid fa-file-pdf"></i>
                            </button>
                            ` : ''}
                        </div>
                    </div>
                `;
            }).join('');
        } else {
            txList.innerHTML = '<div style="color: #94a3b8; text-align: center; padding: 1rem 0;">No active transactions.</div>';
        }
    } catch (err) { console.error('Error fetching client details:', err); }
}

async function getBase64ImageFromUrl(imageUrl) {
    try {
        const res = await fetch(imageUrl);
        if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
        const blob = await res.blob();
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    } catch (err) {
        console.warn("Could not load image:", err);
        return null;
    }
}

function focusNewOrder() {
    document.getElementById('client-select').focus();
}

function initials(name) {
    if (!name) return 'N/A';
    return name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
}

function escHtml(str) {
    return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/* ── Export Generation ───────────────────────── */
async function generatePDFInvoice(order, items) {
    try {
        if (!window.jspdf || !window.jspdf.jsPDF) {
            return alert("PDF library not loaded. Please refresh.");
        }
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF();

        // Add Amiri font from pre-loaded Base64 (amiri_font.js)
        if (window.AmiriBase64) {
            try {
                doc.addFileToVFS('Amiri-Regular.ttf', window.AmiriBase64);
                doc.addFont('Amiri-Regular.ttf', 'Amiri', 'normal');
                doc.addFont('Amiri-Regular.ttf', 'Amiri', 'bold');
                doc.setFont('Amiri');
            } catch (err) {
                console.warn("Could not load Amiri font from window variable.", err);
            }
        } else {
            console.warn("Amiri Base64 font not found. Arabic text may not render correctly.");
        }

        // Background Logo Watermark (Must be added FIRST to sit behind everything)
        const LOGO_BASE64 = 'data:image/png;base64,';
        const logoBase64 = LOGO_BASE64;
        if (logoBase64) {
            try {
                const imgProps = doc.getImageProperties(logoBase64);
                doc.setGState(new doc.GState({ opacity: 0.10 })); // 10% opacity

                const pageWidth = doc.internal.pageSize.getWidth();
                const pageHeight = doc.internal.pageSize.getHeight();

                const imgWidth = 150; // Fixed width request
                const imgHeight = (imgProps.height * imgWidth) / imgProps.width;

                const xCenter = (pageWidth - imgWidth) / 2;
                const yCenter = (pageHeight - imgHeight) / 2;

                doc.addImage(logoBase64, 'PNG', xCenter, yCenter, imgWidth, imgHeight);
                doc.setGState(new doc.GState({ opacity: 1.0 })); // Return to solid for rest of doc
            } catch (imgErr) {
                console.warn("Could not calculate image properties for watermark:", imgErr);
            }
        }

        // Header & Title
        const pageWidth = doc.internal.pageSize.getWidth();

        doc.setFont('Amiri', 'normal');
        doc.setFontSize(22);
        doc.setTextColor(41, 128, 185); // #2980b9
        doc.text(window.fixArabic("مركز القدس 2 للمستلزمات والأجهزة الطبية"), pageWidth / 2, 14, { align: 'center', lang: 'ar' });

        doc.setFontSize(12);
        doc.setTextColor(100, 116, 139); // slate-500
        doc.text(window.fixArabic("فاتورة مبيعات"), pageWidth / 2, 22, { align: 'center', lang: 'ar' });

        // Meta details
        doc.setFontSize(10);
        doc.text(`Order ID: ${order.order_number}`, 140, 28);
        doc.text(`Date: ${order.date}`, 140, 34);

        // Client Info
        doc.setDrawColor(226, 232, 240); // Slate-200
        doc.line(14, 45, 196, 45); // horizontal line

        doc.setFontSize(11);
        doc.setTextColor(15, 23, 42);
        doc.setFont(undefined, "bold");
        doc.text("Billed To:", 14, 55);

        // Clean Title Logic
        let clientDisplayName = order.client_name || 'N/A';
        clientDisplayName = clientDisplayName.replace(/^(صيدلية|دكتور)\s*\/\s*/g, '').replace(/^Dr\.\s*/ig, '').trim();

        doc.setFont(undefined, "normal");
        doc.setTextColor(71, 85, 105);
        doc.text(window.fixArabic(clientDisplayName), 14, 62, { lang: 'ar' });

        // Table
        const tableData = items.map(item => {
            const itemName = item.name || item.product_name || 'Unknown Item';
            const qty = item.qty || item.quantity || 0;
            const unitPrice = Number(item.unit_price || item.price || 0);
            const subtotal = Number(item.subtotal || (qty * unitPrice));

            return [`${subtotal.toFixed(2)}`, `${unitPrice.toFixed(2)}`, qty, window.fixArabic(itemName)];
        });

        doc.autoTable({
            startY: 75,
            head: [['Subtotal', 'Unit Price', 'Qty', 'Item']],
            body: tableData,
            theme: 'grid', // Professional table border
            headStyles: { fillColor: [59, 130, 246], font: 'Amiri', fontStyle: 'normal', halign: 'center' },
            styles: { fontSize: 10, cellPadding: 4, font: 'Amiri', fontStyle: 'normal', lineColor: [200, 200, 200], lineWidth: 0.1 },
            columnStyles: { 0: { cellWidth: 35, halign: 'right' }, 1: { cellWidth: 40, halign: 'center' }, 2: { cellWidth: 25, halign: 'center' }, 3: { cellWidth: 80, halign: 'right' } }
        });

        // Footer
        const finalY = doc.lastAutoTable.finalY + 15;

        doc.setFontSize(14);
        doc.setTextColor(15, 23, 42);
        doc.setFont(undefined, "bold");
        doc.text(`Total Amount:`, 130, finalY);

        doc.setFontSize(16);
        doc.text(`$${Number(order.total_amount).toFixed(2)}`, 165, finalY);

        doc.setFont('Amiri', 'normal');
        doc.setFontSize(10);
        doc.setTextColor(15, 23, 42); // slate-900
        doc.text(window.fixArabic("للتواصل بنا : 01155675246- 01221884709- 01220212028 - 01227831253"), pageWidth / 2, 275, { align: "center", lang: 'ar' });
        doc.text(window.fixArabic("العنوان : اسوان - السيل - شارع المشرحه بجوار مستشفي اسوان الجامعي - مركز القدس 2"), pageWidth / 2, 282, { align: "center", lang: 'ar' });

        doc.save(`Invoice_${order.order_number}.pdf`);
    } catch (err) {
        console.error("PDF Generation Error:", err);
        alert("Failed to generate PDF. Check console for details.");
    }
}

function generateExcelExport(order, items) {
    if (!window.XLSX) {
        return alert("Excel library not loaded. Please refresh.");
    }

    // Transform items for Excel
    const excelData = items.map(item => ({
        "Order ID": order.order_number,
        "Date": order.date,
        "Client": order.client_name,
        "Product": item.name || item.product_name,
        "Quantity": item.qty || item.quantity,
        "Unit Price ($)": Number(item.unit_price || item.price).toFixed(2),
        "Subtotal ($)": Number(item.subtotal || ((item.qty || item.quantity) * (item.unit_price || item.price))).toFixed(2)
    }));

    // Add a blank row and total row
    excelData.push({});
    excelData.push({
        "Product": "TOTAL AMOUNT:",
        "Subtotal ($)": Number(order.total_amount).toFixed(2)
    });

    const worksheet = XLSX.utils.json_to_sheet(excelData);

    // Auto-size columns slightly
    const wscols = [
        { wch: 15 }, { wch: 12 }, { wch: 25 }, { wch: 35 }, { wch: 10 }, { wch: 15 }, { wch: 15 }
    ];
    worksheet['!cols'] = wscols;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Order Details");

    XLSX.writeFile(workbook, `Order_${order.order_number}.xlsx`);
}

// Global wrappers for fetching historical order items before exporting
async function exportOrderPDF(identifier) {
    try {
        // Fetch the specific order's summary by fetching with a large limit
        // (API now returns {orders, total} shape)
        const resList = await fetch(`/api/orders?limit=1000&offset=0`);
        const data = await resList.json();
        const orders = data.orders ?? data; // handle both array and paginated response
        const orderSummary = orders.find(o => o.id == identifier || o.order_number === identifier);
        if (!orderSummary) return alert("Order not found.");

        const resItems = await fetch(`/api/orders/${orderSummary.id}/items`);
        if (!resItems.ok) return alert("Error fetching historic order items.");
        const items = await resItems.json();

        const exportOrderData = {
            order_number: orderSummary.order_number,
            client_name: orderSummary.client_name.replace(/^[⚕️🏪]\s*(Dr:\s*|Pharm:\s*)?/, ''),
            client_type: orderSummary.client_id ? (String(orderSummary.client_id).startsWith('doc') ? 'doctor' : 'pharmacy') : null,
            date: new Date(orderSummary.created_at).toISOString().split('T')[0],
            total_amount: orderSummary.total_amount
        };

        generatePDFInvoice(exportOrderData, items);
    } catch (err) {
        console.error("Export Error:", err);
        alert("Failed to export PDF: " + err.message);
    }
}

