/* ── Returns Logic ───────────────────────────── */
let currentReturnOrderId = null;
async function openReturnModal(orderId, orderNumber) {
    currentReturnOrderId = orderId;
    document.getElementById('return-order-id-display').textContent = orderNumber;
    document.getElementById('return-modal').style.display = 'flex';

    const tbody = document.getElementById('return-items-tbody');
    tbody.innerHTML = '<tr><td colspan="5" class="text-center text-muted">Loading items...</td></tr>';

    try {
        const res = await fetch(`/api/orders/${orderId}/items`);
        const items = await res.json();

        if (items.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" class="text-center text-muted">No items found for this order.</td></tr>';
            return;
        }

        let html = '';
        let hasReturnable = false;

        items.forEach(item => {
            const returnedQty = item.returned_qty || 0;
            const maxReturnable = item.qty - returnedQty;

            if (maxReturnable > 0) hasReturnable = true;

            html += `
                <tr>
                    <td style="font-weight:500;">${escHtml(item.product_name)}</td>
                    <td>$${Number(item.unit_price).toFixed(2)}</td>
                    <td>${maxReturnable} (Purchased: ${item.qty})</td>
                    <td>
                        <input type="number" class="return-qty-input" data-item-id="${item.id}" max="${maxReturnable}" min="0" value="0" ${maxReturnable === 0 ? 'disabled' : ''} style="width: 80px; padding: 5px; border: 1px solid #e2e8f0; border-radius: 4px;">
                    </td>
                    <td>
                        <input type="text" class="return-reason-input" data-item-id="${item.id}" placeholder="Reason (Optional)" ${maxReturnable === 0 ? 'disabled' : ''} style="width: 100%; padding: 5px; border: 1px solid #e2e8f0; border-radius: 4px;">
                    </td>
                </tr>
            `;
        });

        tbody.innerHTML = html;
        document.getElementById('submit-return-btn').disabled = !hasReturnable;

    } catch (err) {
        tbody.innerHTML = `<tr><td colspan="5" class="text-center text-danger">Error loading items: ${err.message}</td></tr>`;
    }
}

function closeReturnModal() {
    document.getElementById('return-modal').style.display = 'none';
    currentReturnOrderId = null;
}

async function submitReturn() {
    if (!currentReturnOrderId) return;

    const qtyInputs = document.querySelectorAll('.return-qty-input');
    const reasonInputs = document.querySelectorAll('.return-reason-input');

    const itemsToReturn = [];

    qtyInputs.forEach((input, index) => {
        const qty = parseInt(input.value) || 0;
        if (qty > 0) {
            const itemId = input.getAttribute('data-item-id');
            const reason = reasonInputs[index].value;
            itemsToReturn.push({ item_id: itemId, return_qty: qty, return_reason: reason });
        }
    });

    if (itemsToReturn.length === 0) {
        alert('Please specify at least one item quantity to return.');
        return;
    }

    const btn = document.getElementById('submit-return-btn');
    const originalContent = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Processing...';

    try {
        const res = await fetch(`/api/orders/${currentReturnOrderId}/return`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ items: itemsToReturn })
        });

        const resClone = res.clone();
        let data;
        try {
            data = await res.json();
        } catch (parseErr) {
            const rawText = await resClone.text();
            throw new Error(`Server returned an invalid JSON response. Please ensure backend connects successfully. Details: ${rawText.substring(0, 50)}...`);
        }

        if (!res.ok) throw new Error(data.error || 'Failed to process return');

        alert(`Return processed successfully! Refund amount: $${Number(data.refund_amount).toFixed(2)}`);
        closeReturnModal();
        loadOrders();

        const currentClientId = document.getElementById('client-select').value;
        if (currentClientId) handleClientSelect(currentClientId);

    } catch (err) {
        alert('Error processing return: ' + err.message);
    } finally {
        btn.disabled = false;
        btn.innerHTML = originalContent;
    }
}

async function generateReturnPDFFromTx(orderId) {
    try {
        const orderRes = await fetch(`/api/orders?limit=1000`);
        const orderData = await orderRes.json();
        const orders = orderData.orders || orderData;
        const order = orders.find(o => o.id == orderId);

        if (!order) throw new Error('Order not found');

        const itemsRes = await fetch(`/api/orders/${orderId}/items`);
        const items = await itemsRes.json();

        const returnedItems = items.filter(i => i.returned_qty > 0).map(i => ({
            name: i.product_name,
            qty: i.returned_qty,
            unit_price: i.unit_price,
            subtotal: i.returned_qty * i.unit_price,
            return_reason: i.return_reason
        }));

        if (returnedItems.length === 0) {
            alert('No returned items found for this order.');
            return;
        }

        const exportOrderData = {
            order_number: 'RET-' + (order.order_number || orderId),
            client_name: order.client_name,
            client_type: 'client',
            date: new Date().toISOString().split('T')[0],
            total_amount: returnedItems.reduce((sum, item) => sum + item.subtotal, 0)
        };

        generateReturnPDF(exportOrderData, returnedItems);

    } catch (err) {
        console.error(err);
        alert('Failed to generate Return PDF: ' + err.message);
    }
}

async function generateReturnPDF(order, items) {
    try {
        if (!window.jspdf || !window.jspdf.jsPDF) return alert("PDF library not loaded. Please refresh.");
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF();

        if (window.AmiriBase64) {
            try {
                doc.addFileToVFS('Amiri-Regular.ttf', window.AmiriBase64);
                doc.addFont('Amiri-Regular.ttf', 'Amiri', 'normal');
                doc.addFont('Amiri-Regular.ttf', 'Amiri', 'bold');
                doc.setFont('Amiri');
            } catch (err) { }
        }

        doc.setFontSize(22);
        doc.setTextColor(30, 41, 59);
        const titleY = 20;

        doc.setFont('Amiri', 'bold');
        doc.text(window.fixArabic("إشعار دائن / مرتجع مبيعات"), 105, titleY, { align: "center", lang: 'ar' });

        doc.setFont('helvetica', 'bold');
        doc.setFontSize(14);
        doc.text("CREDIT NOTE / RETURN", 105, titleY + 7, { align: "center" });

        doc.setFontSize(11);
        doc.setTextColor(71, 85, 105);
        doc.setFont('helvetica', 'normal');

        let billedToName = order.client_name || 'N/A';
        billedToName = billedToName.replace(/^(صيدلية|دكتور)\s*\/\s*/g, '').replace(/^Dr\.\s*/ig, '').replace(/^pharm:\s*/ig, '').trim();

        const detailsY = 45;
        doc.text(`Return Ref: ${order.order_number}`, 14, detailsY);
        doc.text(`Date: ${order.date}`, 14, detailsY + 6);
        doc.text(`Billed To: ${billedToName}`, 120, detailsY);

        const tableColumn = ["Subtotal", "Unit Price", "Reason", "Qty", "Item Description"];
        const tableRows = [];

        items.forEach(item => {
            const reason = item.return_reason || 'N/A';
            const itemData = [`${Number(item.subtotal).toFixed(2)}`, `${Number(item.unit_price).toFixed(2)}`, window.fixArabic(reason), item.qty.toString(), window.fixArabic(item.name)];
            tableRows.push(itemData);
        });

        doc.autoTable({
            head: [tableColumn],
            body: tableRows,
            startY: detailsY + 15,
            theme: 'grid',
            headStyles: { fillColor: [239, 68, 68], textColor: 255, fontSize: 10, fontStyle: 'bold' },
            bodyStyles: { fontSize: 10, textColor: 51 },
            alternateRowStyles: { fillColor: [248, 250, 252] },
            margin: { top: 10, left: 14, right: 14 },
            columnStyles: { 0: { halign: 'right', fontStyle: 'bold' }, 1: { halign: 'right' }, 2: { cellWidth: 40 }, 3: { cellWidth: 20, halign: 'center' }, 4: { cellWidth: 70, halign: 'right' } },
            styles: { fontSize: 10, textColor: 51, font: 'Amiri', cellPadding: 5, halign: 'right' }
        });

        const finalY = doc.lastAutoTable.finalY || 60;
        doc.setFontSize(14);
        doc.setTextColor(30, 41, 59);
        doc.setFont('helvetica', 'bold');
        doc.text(`Total Refund: $${Number(order.total_amount).toFixed(2)}`, 196, finalY + 10, { align: "right" });

        doc.setFontSize(10);
        doc.setTextColor(148, 163, 184);
        doc.setFont('helvetica', 'normal');
        doc.text("Thank you for your business. | Al-Quds Center", 105, 280, { align: "center" });

        doc.setFont('Amiri', 'normal');
        doc.text(window.fixArabic("أسوان , عمارات العرائس , عمارة رقم 36, الشقة 11"), 105, 285, { align: "center", lang: 'ar' });

        doc.save(`${order.order_number}_Return.pdf`);

    } catch (err) {
        console.error("PDF Generate Error:", err);
        alert("Failed to generate PDF.");
    }
}
